{"file_path":"/app/parallel_linear.py","content":"import torch
import torch.nn as nn
import torch.distributed as dist


def _distributed_info():
    """Return (world_size, rank). Defaults to (1, 0) when a process group
    has not been initialized yet (useful for unit tests)."""
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size(), dist.get_rank()
    return 1, 0


class _AllGather(torch.autograd.Function):
    """Gather per-rank tensors and concatenate them along the last dimension.

    The backward pass slices the upstream gradient back to the local chunk,
    matching the semantics used by tensor-parallel all_gather implementations.
    """

    @staticmethod
    def forward(ctx, input_, world_size):
        ctx.world_size = world_size
        if world_size <= 1:
            return input_

        input_ = input_.contiguous()
        chunks = [torch.empty_like(input_) for _ in range(world_size)]
        dist.all_gather(chunks, input_)
        return torch.cat(chunks, dim=-1)

    @staticmethod
    def backward(ctx, grad_output):
        world_size = ctx.world_size
        if world_size <= 1:
            return grad_output, None

        _, rank = _distributed_info()
        chunk_size = grad_output.shape[-1] // world_size
        grad_input = grad_output[
            ..., rank * chunk_size : (rank + 1) * chunk_size
        ].contiguous()
        return grad_input, None


class _AllReduce(torch.autograd.Function):
    """Sum a tensor across all ranks and broadcast the result.

    The backward pass is the identity because every rank's local partial
    output contributes with coefficient one to the summed output.
    """

    @staticmethod
    def forward(ctx, input_, world_size):
        ctx.world_size = world_size
        if world_size <= 1:
            return input_

        input_ = input_.contiguous()
        dist.all_reduce(input_)
        return input_

    @staticmethod
    def backward(ctx, grad_output):
        return grad_output, None


class ColumnParallelLinear(nn.Module):
    """Linear layer whose weight matrix is sharded along the output dimension.

    On each rank:
        local_out = input @ weight_local [+ bias_local]
        output   = all_gather(local_out)          # concat along last dimension

    The bias is sharded in exactly the same way as the output dimension.
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size, self.rank = _distributed_info()

        master_weight = master_weight.detach().clone()

        # Accept either the natural (in_features, out_features) layout used
        # for x @ W, or the PyTorch nn.Linear layout (out_features,
        # in_features). The split is always along the output dimension.
        if tuple(master_weight.shape) == (in_features, out_features):
            self._transposed = False
            output_dim = 1
        elif tuple(master_weight.shape) == (out_features, in_features):
            self._transposed = True
            output_dim = 0
        else:
            raise ValueError(
                f"master_weight shape {tuple(master_weight.shape)} does not "
                f"match (in_features={in_features}, out_features={out_features})"
            )

        out_chunk = out_features // self.world_size
        if self._transposed:
            # [out_features, in_features] -> [out_features/world_size, in_features]
            local_weight = master_weight[
                self.rank * out_chunk : (self.rank + 1) * out_chunk, :
            ]
        else:
            # [in_features, out_features] -> [in_features, out_features/world_size]
            local_weight = master_weight[
                :, self.rank * out_chunk : (self.rank + 1) * out_chunk
            ]

        self.weight = nn.Parameter(local_weight)

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(
                    out_chunk,
                    dtype=master_weight.dtype,
                    device=master_weight.device,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        if self._transposed:
            local_out = torch.nn.functional.linear(x, self.weight, self.bias)
        else:
            local_out = torch.matmul(x, self.weight)
            if self.bias is not None:
                local_out = local_out + self.bias

        return _AllGather.apply(local_out, self.world_size)


class RowParallelLinear(nn.Module):
    """Linear layer whose weight matrix is sharded along the input dimension.

    On each rank:
        local_out = input_local @ weight_local
        output    = all_reduce(local_out)          # sum across ranks
        output    = output + bias                   # full bias on every rank
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size, self.rank = _distributed_info()

        master_weight = master_weight.detach().clone()

        if tuple(master_weight.shape) == (in_features, out_features):
            self._transposed = False
            input_dim = 0
        elif tuple(master_weight.shape) == (out_features, in_features):
            self._transposed = True
            input_dim = 1
        else:
            raise ValueError(
                f"master_weight shape {tuple(master_weight.shape)} does not "
                f"match (in_features={in_features}, out_features={out_features})"
            )

        in_chunk = in_features // self.world_size
        if self._transposed:
            # [out_features, in_features] -> [out_features, in_features/world_size]
            local_weight = master_weight[
                :, self.rank * in_chunk : (self.rank + 1) * in_chunk
            ]
        else:
            # [in_features, out_features] -> [in_features/world_size, out_features]
            local_weight = master_weight[
                self.rank * in_chunk : (self.rank + 1) * in_chunk, :
            ]

        self.weight = nn.Parameter(local_weight)

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(
                    out_features,
                    dtype=master_weight.dtype,
                    device=master_weight.device,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        if self._transposed:
            partial = torch.nn.functional.linear(x, self.weight)
        else:
            partial = torch.matmul(x, self.weight)

        out = _AllReduce.apply(partial, self.world_size)
        if self.bias is not None:
            out = out + self.bias
        return out
